CREATE DATABASE IF NOT EXISTS restaurant_management;
USE restaurant_management;
CREATE TABLE dining_area (area_id INT PRIMARY KEY AUTO_INCREMENT, area_name VARCHAR(100) NOT NULL, floor_no INT);
CREATE TABLE dining_table (table_id INT PRIMARY KEY AUTO_INCREMENT, area_id INT NOT NULL, table_no INT NOT NULL, capacity INT NOT NULL, status VARCHAR(30) DEFAULT 'Available', FOREIGN KEY (area_id) REFERENCES dining_area(area_id));
CREATE TABLE customer (customer_id INT PRIMARY KEY AUTO_INCREMENT, full_name VARCHAR(100) NOT NULL, phone VARCHAR(20), email VARCHAR(100));
CREATE TABLE waiter (waiter_id INT PRIMARY KEY AUTO_INCREMENT, full_name VARCHAR(100) NOT NULL, shift VARCHAR(30));
CREATE TABLE menu_item (item_id INT PRIMARY KEY AUTO_INCREMENT, item_name VARCHAR(100) NOT NULL, category VARCHAR(50), price DECIMAL(10,2) NOT NULL);
CREATE TABLE reservation (reservation_id INT PRIMARY KEY AUTO_INCREMENT, customer_id INT NOT NULL, table_id INT NOT NULL, start_time DATETIME NOT NULL, end_time DATETIME, guest_count INT NOT NULL, res_status VARCHAR(30) DEFAULT 'Reserved', FOREIGN KEY (customer_id) REFERENCES customer(customer_id), FOREIGN KEY (table_id) REFERENCES dining_table(table_id));
CREATE TABLE orders (order_id INT PRIMARY KEY AUTO_INCREMENT, table_id INT NOT NULL, waiter_id INT NOT NULL, order_time DATETIME DEFAULT CURRENT_TIMESTAMP, order_status VARCHAR(30) DEFAULT 'Pending', FOREIGN KEY (table_id) REFERENCES dining_table(table_id), FOREIGN KEY (waiter_id) REFERENCES waiter(waiter_id));
CREATE TABLE order_item (order_item_id INT PRIMARY KEY AUTO_INCREMENT, order_id INT NOT NULL, item_id INT NOT NULL, quantity INT NOT NULL, unit_price DECIMAL(10,2) NOT NULL, FOREIGN KEY (order_id) REFERENCES orders(order_id), FOREIGN KEY (item_id) REFERENCES menu_item(item_id));
CREATE TABLE discount (discount_id INT PRIMARY KEY AUTO_INCREMENT, code VARCHAR(50) UNIQUE NOT NULL, percent DECIMAL(5,2) NOT NULL, authorized_by INT, FOREIGN KEY (authorized_by) REFERENCES waiter(waiter_id));
CREATE TABLE bill (bill_id INT PRIMARY KEY AUTO_INCREMENT, order_id INT UNIQUE NOT NULL, discount_id INT, subtotal DECIMAL(10,2) NOT NULL, tax_amount DECIMAL(10,2) NOT NULL, total_amount DECIMAL(10,2) NOT NULL, bill_status VARCHAR(30) DEFAULT 'Unpaid', FOREIGN KEY (order_id) REFERENCES orders(order_id), FOREIGN KEY (discount_id) REFERENCES discount(discount_id));
CREATE TABLE payment (payment_id INT PRIMARY KEY AUTO_INCREMENT, bill_id INT NOT NULL, amount_paid DECIMAL(10,2) NOT NULL, pay_method VARCHAR(30) NOT NULL, pay_time DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (bill_id) REFERENCES bill(bill_id));
CREATE TABLE kitchen_ticket (ticket_id INT PRIMARY KEY AUTO_INCREMENT, order_item_id INT NOT NULL, sent_time DATETIME, ready_time DATETIME, ticket_status VARCHAR(30) DEFAULT 'Pending', FOREIGN KEY (order_item_id) REFERENCES order_item(order_item_id));
